
import urllib.request, json, time
HDRS = {"tokenid": "b06663c4-62df-41b7-9111-6653e6b54592", "Content-Type": "application/json"}
SAMPLE = [["505517688", 649.0], ["483713079", 566.0], ["458863410", 566.0], ["468736671", 349.0], ["491525549", 349.0], ["502184186", 566.0], ["466735952", 520.0], ["508898664", 649.0], ["486970995", 285.0], ["490021882", 349.0], ["503762950", 265.0], ["509216286", 349.0], ["507229710", 649.0], ["478072036", 649.0], ["480868101", 159.0], ["481224142", 425.0], ["458586183", 649.0], ["508229161", 649.0], ["473817631", 349.0], ["507196174", 532.0], ["462523850", 335.0], ["507254631", 349.0], ["503442902", 349.0], ["474637954", 425.0], ["509825483", 649.0], ["492014984", 300.0], ["503775901", 649.0], ["491790750", 379.0], ["477562162", 425.0], ["499581898", 649.0], ["459404065", 566.0], ["483213556", 349.0], ["472296126", 385.0], ["484906678", 566.0], ["457270971", 425.0], ["464406809", 349.0], ["470343790", 349.0], ["466974598", 304.0], ["492088050", 425.0], ["462509087", 349.0], ["460807688", 349.0], ["474644387", 495.0], ["482775972", 425.0], ["468765395", 494.0], ["477812131", 197.0], ["468328124", 600.0], ["468889551", 494.0], ["457305093", 349.0], ["498082776", 385.0], ["459391541", 649.0], ["465420910", 677.0], ["487873859", 265.0], ["470201895", 349.0], ["508232951", 495.0], ["458353274", 349.0], ["505890443", 495.0], ["495690702", 649.0], ["510112452", 349.0], ["472115338", 566.0], ["470729374", 300.0]]
nulls = 0; oks = 0
for i in range(0, len(SAMPLE), 20):
    chunk = [r for r, a in SAMPLE[i:i+20]]
    req = urllib.request.Request("https://api.fireberry.com/api/v3/query",
        data=json.dumps({"objectType": 1018,
            "fields": [{"name":"pcfReference"},{"name":"pcfPayed"}],
            "pageSize": 50, "pageNumber": 1,
            "filter": [{"type":"and","conditions":[
                {"fieldName":"pcfReference","operator":"eq-in","value":chunk}]}]}).encode(), headers=HDRS)
    r = urllib.request.urlopen(req, timeout=30)
    rows = json.loads(r.read()).get("data", [])
    for x in rows:
        if x.get("pcfPayed") is None: nulls += 1
        else: oks += 1
    time.sleep(0.5)
print(f"sample: oks={oks} nulls={nulls} ratio_null={nulls/(oks+nulls):.2%}")
